// ============================================================
//  n8n · Code node · "Armar dashboard v4" · Run Once for All Items
//  Cambios v4: clasificacion de TC_agente robusta a mayus/espacios
//  (matchea total general | sin asignar | agente n8n), y la grafica
//  de agentes detecta sus columnas sola (no depende de nombres fijos).
//  Modo dual: ?format=json devuelve el payload para el refresh.
// ============================================================

const TEMPLATE_B64 = "";


// ---- normaliza filas: headers sin espacios, strings recortados
function norm(item) {
  const row = {};
  for (const [k, v] of Object.entries(item.json || {})) {
    row[String(k).trim()] = typeof v === 'string' ? v.trim() : v;
  }
  return row;
}
const rows = $input.all().map(norm);

// ---- clasifica por firma de columnas (robusto a mayus/espacios)
const has  = (r, k) => Object.prototype.hasOwnProperty.call(r, k);
const kn   = k => String(k).toLowerCase().replace(/\s+/g, ' ').trim();
const keys = r => Object.keys(r).map(kn);
const hasN = (r, t) => keys(r).includes(t);

const daily = [], cierres = [], tokens = [], ignorados = [],
      escalaciones = [], agentes = [], conexion = [], agentesDia = [];

for (const r of rows) {
  if (has(r, 'entradas'))                     { daily.push(r); continue; }
  if (has(r, 'cerradas_sistema'))             { cierres.push(r); continue; }
  if (has(r, 'costo_total_usd'))              { tokens.push(r); continue; }
  if (has(r, 'total_ignorados'))              { ignorados.push(r); continue; }
  if (has(r, 'total_escalaciones'))           { escalaciones.push(r); continue; }
  if (has(r, 'horas_conectado'))              { conexion.push(r); continue; }
  // TC_agente: cualquiera de estas columnas (tolerante a mayus/espacios)
  if (hasN(r,'total general') || hasN(r,'sin asignar') || hasN(r,'agente n8n')) { agentesDia.push(r); continue; }
  if (has(r, 'status') && has(r, 'agent_id')) { agentes.push(r); continue; }
}

// ---- fechas a texto YYYY-MM-DD y orden ascendente
const day = f => String(f ?? '').slice(0, 10);
const sortF = arr => arr.sort((a, b) => (day(a.fecha) < day(b.fecha) ? -1 : 1));
[daily, cierres, tokens, ignorados, escalaciones, conexion, agentesDia].forEach(sortF);

const payload = {
  generated_at: new Date().toISOString(),
  daily, cierres, tokens, ignorados, escalaciones, agentes,
  agentes_dia: agentesDia,
  conexion: (() => {
    if (!conexion.length) return [];
    const last = day(conexion[conexion.length - 1].fecha);
    return conexion.filter(r => day(r.fecha) === last);
  })()
};

// ---- modo dual
let format = '';
try { format = ($('Webhook').first().json.query || {}).format || ''; } catch (e) {}

if (format === 'json') {
  return [{ json: { html: JSON.stringify(payload) } }];
}

const html = Buffer.from(TEMPLATE_B64, 'base64')
  .toString('utf8')
  .replace('__EMBEDDED_DATA__', JSON.stringify(payload));

return [{ json: { html } }];
